#!/usr/bin/env Rscript

# Script: 06_vec2pca.R
# Purpose: Transform FlashPCA output (.vec) into PCA plots.
# Inputs:
#   - WD/outputs/intermediate/pca/*.vec (generated by 05_bcf2pca.sh)
#   - WD/data/pcaannot_1kgppg.txt
#   - WD/data/pcaanot_bbj1kyapp.txt
# Outputs:
#   - WD/outputs/plots/PCA_<prefix>.png

cat("SUBSTEP 0: LOADING R PACKAGES\n")
suppressPackageStartupMessages({
  library(ggplot2)
  library(ggrepel)
  library(dplyr)
})

# ----------------------------- USER CONFIGURATION -------------------------#
# Swap X and Y axis on the PCA plot.
# Off by default; will be set to TRUE for Filtered/Merged plots automatically.
swap_xy <- FALSE
#--------------------------------------------------------------------#

# --------------- AUTO-DISCOVER INPUTS (WD-relative) -------------------------#
args <- commandArgs(trailingOnly = FALSE)
script_path <- sub("^--file=", "", args[grep("^--file=", args)])

if (length(script_path) == 0) {
  script_dir <- getwd()
} else {
  script_dir <- dirname(normalizePath(script_path))
}

# Repo root (WD) is parent of scripts/
WD <- normalizePath(file.path(script_dir, ".."))

pca_dir <- file.path(WD, "outputs", "intermediate", "pca")
vec_files <- Sys.glob(file.path(pca_dir, "*.vec"))

cat("SUBSTEP 1: DISCOVERING INPUT FILES\n")
cat(paste0("WD: ", WD, "\n"))
cat(paste0("PCA dir: ", pca_dir, "\n"))
cat(paste0("Discovered .vec files: ", paste(basename(vec_files), collapse = ", "), "\n"))
if (length(vec_files) == 0) {
  stop(paste0("[e] No .vec files found in: ", pca_dir))
}

fp_annot_pg1kgppg <- file.path(WD, "data", "pcaannot_1kgppg.txt")
fp_annot_bbjyapp <- file.path(WD, "data", "pcaanot_bbj1kyapp.txt")

if (!file.exists(fp_annot_pg1kgppg)) stop(paste0("[e] Missing annotation: ", fp_annot_pg1kgppg))
if (!file.exists(fp_annot_bbjyapp)) stop(paste0("[e] Missing annotation: ", fp_annot_bbjyapp))

# --------------------------------------------------------------#
# other configurable parameters
legend_attach <- TRUE
plot_width <- 13
plot_height <- 10
# ---------- EXECUTION -----------------#
cat("SUBSTEP 2: SETUP OUTPUT DIRECTORY\n")
outdir <- file.path(WD, "outputs", "plots")
dir.create(outdir, recursive = TRUE, showWarnings = FALSE)

cat("SUBSTEP 3: GENERATING PCA PLOTS\n")

# Decide to swap PC1 and PC2 for filtered/merged plots and don't swap for control.
for (file in vec_files) {
  # Decide plot title from filename
  if (grepl("Control|BBJ1K|YAPO|JAPP", basename(file), ignore.case = TRUE)) {
    plot_main <- "Control"
    swap_xy <- FALSE
  } 
  if (grepl("Filtered|Merged|LociBased", basename(file), ignore.case = TRUE)) {
    plot_main <- "Filtered"
    swap_xy <- TRUE
  }  
  # Naming
  OUTPREFIX <- sub(pattern = "(.*)\\..*$", replacement = "\\1", basename(file))
  print(OUTPREFIX)
  
  # Read eigenvect files 
  eigenvect<- read.delim(file)
  eigenvect <- as.data.frame(eigenvect)
  rownames(eigenvect) <- eigenvect[,1]
  eigenvect <- subset(eigenvect, select = -FID) # drop FID column
  names(eigenvect) <- paste0("PC", (1:ncol(eigenvect) - 1))
  names(eigenvect)[1] <- "sample.id"
  cat(paste0("  Samples in plot: ", length(eigenvect$sample.id), "\n"))
  
  # Read annotation files (phenotypes)
  pcaannot_PG1KGP <- read.delim(fp_annot_pg1kgppg)
  pcaannot_BBJYAPP <- read.delim(fp_annot_bbjyapp)
  
  # decide which annot to use based on number of samples, 
  if (length(eigenvect$sample.id) < 100) {
    pcaannot <- pcaannot_PG1KGP
  } else {
    pcaannot <- pcaannot_BBJYAPP
    pcaannot <- dplyr::select(pcaannot, sample.id, project) #drop uneeded columns
  }
  
  #Combine annotation df with eigenvect dataframe
  pca_df<- dplyr::left_join(eigenvect[1:3], pcaannot, by='sample.id')
  #Plot with sample names as labels
  # if
  if (swap_xy == TRUE) {
    myplot <- ggplot(pca_df, aes(x = PC2, y = -PC1, colour = project)) +
    geom_point(alpha=0.7, size = 2) +
    ggtitle(plot_main) +
    theme_classic()
  } else {
    myplot <- ggplot(pca_df, aes(x = PC1, y = PC2, colour = project)) +
    geom_point(alpha=0.7, size = 2) +
    ggtitle(plot_main) +
    theme_classic()
  }    
  
  # handle legend toggle
  if (!legend_attach){
    myplot <- myplot + theme(legend.position = "none") 
  }
  
  # print plot for interactive runs
  print(myplot)
  
  # save plot as OUTPREFIX.png 
  ggsave(file.path(outdir, paste0("PCA_", OUTPREFIX, ".png")),
         plot = myplot, width=plot_width, height=plot_height, units= "cm")
}
cat("SUBSTEP 4: DONE\n")
cat("PCA saved to: ")
cat(outdir)
cat("\n")